-- Keep lead-note mutations and their audit events in one transaction.
create function public.assert_lead_note_actor(p_actor_id uuid) returns text language plpgsql security definer set search_path=pg_catalog,public as $$ declare v_role text; begin select role into v_role from public.users where id=p_actor_id; if p_actor_id is null or v_role not in ('attorney','admin') then raise exception 'Attorney or admin access required' using errcode='42501'; end if; return v_role; end $$;

create function public.create_lead_note_with_activity(p_lead_id uuid,p_body text,p_actor_id uuid) returns public.lead_notes language plpgsql security definer set search_path=pg_catalog,public as $$ declare v public.lead_notes; begin perform public.assert_lead_note_actor(p_actor_id); insert into public.lead_notes(lead_id,body,actor_id) values(p_lead_id,trim(p_body),p_actor_id) returning * into v; insert into public.lead_activity(lead_id,event_type,title,detail,actor_id) values(p_lead_id,'note_added','Note added',v.body,p_actor_id); return v; end $$;
create function public.update_lead_note_with_activity(p_lead_id uuid,p_note_id uuid,p_body text,p_actor_id uuid) returns public.lead_notes language plpgsql security definer set search_path=pg_catalog,public as $$ declare v public.lead_notes; v_role text; begin v_role:=public.assert_lead_note_actor(p_actor_id); select * into v from public.lead_notes where id=p_note_id and lead_id=p_lead_id; if not found then raise exception 'Note not found' using errcode='P0002'; end if; if v.actor_id<>p_actor_id and v_role<>'admin' then raise exception 'Forbidden' using errcode='42501'; end if; update public.lead_notes set body=trim(p_body) where id=p_note_id returning * into v; insert into public.lead_activity(lead_id,event_type,title,actor_id) values(p_lead_id,'note_updated','Note updated',p_actor_id); return v; end $$;
create function public.delete_lead_note_with_activity(p_lead_id uuid,p_note_id uuid,p_actor_id uuid) returns void language plpgsql security definer set search_path=pg_catalog,public as $$ declare v public.lead_notes; v_role text; begin v_role:=public.assert_lead_note_actor(p_actor_id); select * into v from public.lead_notes where id=p_note_id and lead_id=p_lead_id; if not found then raise exception 'Note not found' using errcode='P0002'; end if; if v.actor_id<>p_actor_id and v_role<>'admin' then raise exception 'Forbidden' using errcode='42501'; end if; delete from public.lead_notes where id=p_note_id; insert into public.lead_activity(lead_id,event_type,title,actor_id) values(p_lead_id,'note_deleted','Note deleted',p_actor_id); end $$;
create function public.create_lead_meeting_note_with_activity(p_lead_id uuid,p_title text,p_meeting_date timestamptz,p_attendees text[],p_body text,p_actor_id uuid) returns public.lead_meeting_notes language plpgsql security definer set search_path=pg_catalog,public as $$ declare v public.lead_meeting_notes; begin perform public.assert_lead_note_actor(p_actor_id); insert into public.lead_meeting_notes(lead_id,title,meeting_date,attendees,body,source,actor_id) values(p_lead_id,trim(p_title),p_meeting_date,p_attendees,trim(p_body),'manual',p_actor_id) returning * into v; insert into public.lead_activity(lead_id,event_type,title,detail,actor_id) values(p_lead_id,'meeting_note_added','Meeting note added',v.title,p_actor_id); return v; end $$;
create function public.import_lead_granola_note_with_activity(p_lead_id uuid,p_title text,p_meeting_date timestamptz,p_attendees text[],p_body text,p_granola_note_id text,p_actor_id uuid) returns table(meeting_note public.lead_meeting_notes,imported boolean) language plpgsql security definer set search_path=pg_catalog,public as $$ declare v public.lead_meeting_notes; v_imported boolean; begin perform public.assert_lead_note_actor(p_actor_id); insert into public.lead_meeting_notes(lead_id,title,meeting_date,attendees,body,source,granola_note_id,actor_id) values(p_lead_id,trim(p_title),p_meeting_date,p_attendees,trim(p_body),'granola',p_granola_note_id,p_actor_id) on conflict (lead_id,granola_note_id) where granola_note_id is not null do nothing returning * into v; v_imported:=found; if v_imported then insert into public.lead_activity(lead_id,event_type,title,detail,actor_id) values(p_lead_id,'meeting_note_added','Granola meeting note imported',v.title,p_actor_id); else select * into v from public.lead_meeting_notes where lead_id=p_lead_id and granola_note_id=p_granola_note_id; if not found then raise exception 'Imported note not found' using errcode='P0002'; end if; end if; meeting_note:=v; imported:=v_imported; return next; end $$;
revoke all on function public.assert_lead_note_actor(uuid) from public,anon,authenticated;
revoke all on function public.create_lead_note_with_activity(uuid,text,uuid),public.update_lead_note_with_activity(uuid,uuid,text,uuid),public.delete_lead_note_with_activity(uuid,uuid,uuid),public.create_lead_meeting_note_with_activity(uuid,text,timestamptz,text[],text,uuid) from public,anon,authenticated;
grant execute on function public.create_lead_note_with_activity(uuid,text,uuid),public.update_lead_note_with_activity(uuid,uuid,text,uuid),public.delete_lead_note_with_activity(uuid,uuid,uuid),public.create_lead_meeting_note_with_activity(uuid,text,timestamptz,text[],text,uuid) to service_role;
revoke all on function public.import_lead_granola_note_with_activity(uuid,text,timestamptz,text[],text,text,uuid) from public,anon,authenticated;
grant execute on function public.import_lead_granola_note_with_activity(uuid,text,timestamptz,text[],text,text,uuid) to service_role;
